type Team = { name:string; abbreviation:string; probablePitcher:string|null; starter:{playerId:number|null;era:number;innings:number;gamesStarted:number;runAdjustment:number;strikeOuts:number;expectedStrikeouts:number|null}|null; expectedRuns:number; winProbability:number; fairPrice:string };
type Hitter={id:number;name:string;battingOrder:number;confirmed:boolean;avg:string|null;ops:string|null;expectedHits:number|null;onePlusHitProbability:number|null;fairPrice:string|null};
type ProjectionGame = { id:number; startsAt:string|null; status:string; venue:string; park:{factor:number;priorGames:number;sourceCutoff:string}; weather:{condition:string|null;temperature:number|null;wind:string|null;roof:string|null}; quality:{teamRecords:boolean;starterStats:boolean;awayStarter:boolean;homeStarter:boolean;lineups:boolean;weather:boolean;parkSample:boolean;bullpen:boolean;opponentStrikeouts:boolean;platoon:boolean;validatedMarkets:{moneyline:boolean;total:boolean;firstFive:boolean;firstInning:boolean;pitcherStrikeouts:boolean;hitterHits:boolean};blockingReasons:string[]}; uncertainty:number; away:Team; home:Team; total:{line:number;expectedRuns:number;overProbability:number;underProbability:number;overFairPrice:string;underFairPrice:string}; firstFive:{expectedRuns:number;awayWinProbability:number;homeWinProbability:number;pushProbability:number;awayFairPrice:string;homeFairPrice:string}; firstInning:{expectedRuns:number;nrfiProbability:number;yrfiProbability:number;nrfiFairPrice:string;yrfiFairPrice:string}; lineups:{away:Hitter[];home:Hitter[];confirmed:boolean}; drivers:string[]; recommendation:{reason:string} };
type ModelInfo={name:string;calibrated:boolean;calibrationScope?:string;calibrationPoints?:number;featureCutoff?:string;omissions:string[]};
type Coverage={available:number;expected:number};
type DataHealth={score:number;coverage:{teams:Coverage;starters:Coverage;lineups:Coverage;hitters:Coverage;weather:Coverage;parks:Coverage;bullpens:Coverage;opponentStrikeouts:Coverage;platoonSplits:Coverage;rosterStatuses:Coverage};featureCutoff:string;historicalFinals:number;calibrated:boolean;retrievedAt:string};
type ApiResponse = { games:ProjectionGame[]; retrievedAt:string; error?:string; model?:ModelInfo;dataHealth?:DataHealth };
type BacktestMarketMetric={count:number;accuracy:number|null;brier:number|null;logLoss:number|null};
type CalibrationMetrics={count:number;brier:number;logLoss:number;rawBrier:number;rawLogLoss:number;rawEce:number;selectedMethod:string;selectedBrier:number;selectedLogLoss:number;verified:boolean};
type Backtest = { gamesIngested:number; through:string; metrics:{count:number;accuracy:number|null;brier:number|null;logLoss:number|null;totalMae:number|null}; marketMetrics:{moneyline:BacktestMarketMetric;totalOver85:BacktestMarketMetric;firstFiveHome:BacktestMarketMetric;nrfi:BacktestMarketMetric}; calibratedMetrics:CalibrationMetrics|null;marketCalibratedMetrics:{totalOver85:CalibrationMetrics|null;firstFiveHome:CalibrationMetrics|null;nrfi:CalibrationMetrics|null}; calibration:Array<{low:number;high:number;count:number;predicted:number|null;actual:number|null}>; error?:string };
type ProspectivePerformance={issued:number;settledNow:number;status:Record<string,number>;total:{count:number;accuracy:number|null;brier:number|null};markets:Array<{market:string;count:number;accuracy:number|null;brier:number|null}>;bands:Array<{label:string;count:number;accuracy:number|null;brier:number|null}>};
type LedgerBet={id:string;game_id:number;game_date:string;starts_at:string|null;matchup:string;market:string;selection:string;selection_key:string|null;line:number|null;american_odds:number;model_probability:number;edge:number;stake_units:number;status:string;profit_units:number|null;closing_odds:number|null;closing_opposite_odds:number|null;closing_line_value:number|null;created_at:string};
type ConsensusSide={medianAmerican:number;books:number;bestAmerican:number;bestBook:string;pairedOppositeAmerican:number|null}|null;
type ConsensusGame={homeTeam:string;awayTeam:string;bookmakers:number;moneyline:{home:ConsensusSide;away:ConsensusSide};total:{line:number;over:ConsensusSide;under:ConsensusSide}|null};
type OddsResponse={configured:boolean;provider:string;games:ConsensusGame[];retrievedAt?:string;message?:string};
type OddsVault={summary:{observations:number;games:number;first_observed_at:string|null;last_observed_at:string|null};providers:{oddsPapi:{configured:boolean;historicalFrom:string;status:string};theOddsApi:{configured:boolean;status:string}};cost:string};

function shiftDate(date:string, amount:number) { const next=new Date(`${date}T12:00:00Z`); next.setUTCDate(next.getUTCDate()+amount); return next.toISOString().slice(0,10); }
function time(value:string|null) { return value ? new Intl.DateTimeFormat("en-US",{hour:"numeric",minute:"2-digit",timeZoneName:"short"}).format(new Date(value)) : "Time TBD"; }
function Ring({value}:{value:number}) { return <span className="confidence" style={{"--score":`${value*3.6}deg`} as React.CSSProperties}><span>{value}</span></span>; }

function RecommendationBoard({games,board,onSelect}:{games:ProjectionGame[];board:ReturnType<typeof dailyPicks>;onSelect:(id:number)=>void}){
  return <section className="recommendation-board" aria-labelledby="recommended-title"><div className="section-head"><div><p className="eyebrow">DAILY MODEL PICKS</p><h2 id="recommended-title">Recommended picks summary</h2><p className="board-intro">Ranked statistical suggestions with at least 55% model probability. Check the sportsbook price in the matchup lab before betting.</p></div><span className="price-required">PRICE CHECK REQUIRED</span></div>{board.recommended.length?<div className="recommended-list">{board.recommended.map((pick,index)=><button key={pick.id} onClick={()=>onSelect(pick.gameId)}><b>#{index+1}</b><span><small>{pick.matchup} · {pick.market}</small><strong>{pick.selection}</strong><em>{pick.explanation}</em></span><span className="pick-probability">{(pick.probability*100).toFixed(1)}%<small>Fair {pick.fairPrice}</small></span></button>)}</div>:<div className="board-empty">No market clears the model’s 55% and validation gates for this date. That is a valid pass, not an error.</div>}<div className="games-board">{games.map(game=>{const records=(game as ProjectionGame&{records?:{away:{wins:number;losses:number};home:{wins:number;losses:number}}}).records;return <article key={game.id}><button className="game-board-head" onClick={()=>onSelect(game.id)}><span><small>{time(game.startsAt)} · {game.status}</small><strong>{game.away.abbreviation} @ {game.home.abbreviation}</strong></span><span>Analyze prices →</span></button><div className="matchup-teams"><div><b>{game.away.name}</b><span>{records?`${records.away.wins}-${records.away.losses}`:"Record pending"} · {game.away.probablePitcher??"Starter TBD"}</span></div><div><b>{game.home.name}</b><span>{records?`${records.home.wins}-${records.home.losses}`:"Record pending"} · {game.home.probablePitcher??"Starter TBD"}</span></div></div><div className="possible-picks">{(board.byGame.get(game.id)??[]).map(pick=><div key={pick.id} className={pick.recommended?"suggested":"lean"}><small>{pick.market}</small><strong>{pick.selection}</strong><span>{(pick.probability*100).toFixed(1)}% · fair {pick.fairPrice}</span><p>{pick.explanation}</p><em>{pick.recommended?"MODEL PICK":"LEAN / PASS"}</em></div>)}</div></article>})}</div></section>;
}

function OpportunityBoard({games,board,onSelect}:{games:ProjectionGame[];board:ReturnType<typeof dailyPicks>;onSelect:(id:number)=>void}){
  const [filter,setFilter]=useState<"ALL"|ReturnType<typeof dailyPicks>["categories"][number]>("ALL");
  const [expanded,setExpanded]=useState<number|null>(null);
  const visible=filter==="ALL"?board.recommended:board.all.filter(pick=>pick.market===filter&&pick.probability>=.55).sort((a,b)=>Number(b.validated)-Number(a.validated)||b.probability-a.probability).slice(0,12);
  return <section className="opportunity-board" aria-labelledby="opportunity-title"><header className="opportunity-head"><div><p className="eyebrow">DAILY RESEARCH BOARD</p><h2 id="opportunity-title">Highest conservative probabilities across every market</h2><p>These are ranked model leans, not certified picks. Percentages are reduced according to model uncertainty; sportsbook price still determines value.</p></div><div className="board-key"><span><i className="verified-dot"/>Live-proven (none yet)</span><span><i className="research-dot"/>Research estimate</span></div></header><nav className="market-filter" aria-label="Filter picks by market"><button className={filter==="ALL"?"active":""} onClick={()=>setFilter("ALL")}>Highest estimates</button>{board.categories.map(category=><button key={category} className={filter===category?"active":""} onClick={()=>setFilter(category)}>{category}</button>)}</nav>
    <div className="opportunity-table"><div className="opportunity-row heading"><span>Rank / matchup</span><span>Model selection</span><span>Probability</span><span>Fair price</span><span>Status</span></div>{visible.map((pick,index)=><button className="opportunity-row" key={pick.id} onClick={()=>onSelect(pick.gameId)}><span><b>#{index+1}</b><small>{pick.matchup} · {pick.market}</small></span><span><strong>{pick.selection}</strong><small>{pick.explanation}</small></span><span className="big-probability">{(pick.probability*100).toFixed(1)}%</span><span className="fair-chip">{pick.fairPrice}</span><span className={pick.validated?"validation verified":"validation research"}>{pick.validated?"LIVE-PROVEN":"UNVERIFIED"}</span></button>)}</div>
    {!visible.length&&<div className="board-empty">No option in this market currently clears 55%. Passing is better than forcing a pick.</div>}
    <div className="game-review-grid">{games.map(game=>{const rows=board.byGame.get(game.id)??[],open=expanded===game.id,missing=[!game.quality.starterStats?"starter stats":null,!game.quality.lineups?"confirmed lineups":null,!game.quality.weather?"weather":null,!game.quality.bullpen?"bullpen workload":null,!game.quality.parkSample?"park sample":null].filter(Boolean);return <article className={open?"open":""} key={game.id}><button className="review-game-head" onClick={()=>setExpanded(open?null:game.id)}><span><small>{time(game.startsAt)} · {game.status}</small><strong>{game.away.abbreviation} @ {game.home.abbreviation}</strong><em>{game.away.probablePitcher??"TBD"} vs {game.home.probablePitcher??"TBD"}</em></span><span><b>{rows.length}</b> markets <i>{open?"−":"+"}</i></span></button><div className="coverage-strip"><span className={missing.length?"incomplete":"complete"}>{missing.length?`Missing: ${missing.join(", ")}`:"Core inputs complete"}</span><span>Projected {game.away.expectedRuns}–{game.home.expectedRuns}</span></div>{open&&<div className="market-cards">{rows.sort((a,b)=>b.probability-a.probability).map(pick=><button key={pick.id} onClick={()=>onSelect(game.id)}><small>{pick.market}</small><strong>{pick.selection}</strong><b>{(pick.probability*100).toFixed(1)}%</b><span>Fair {pick.fairPrice}</span><p>{pick.explanation}</p><em className={pick.validated?"verified":"research"}>{pick.validated?"LIVE-PROVEN":"UNVERIFIED LIVE MODEL"}</em><i>{pick.inputNote}</i></button>)}</div>}</article>})}</div>
  </section>;
}

function GameStudy({game,picks}:{game:ProjectionGame|null;picks:ReturnType<typeof dailyPicks>["all"]}){
  if(!game)return null;const records=(game as ProjectionGame&{records?:{away:{wins:number;losses:number};home:{wins:number;losses:number}}}).records,missing=[!game.quality.teamRecords?"team records":null,!game.quality.starterStats?"probable-starter statistics":null,!game.quality.bullpen?"recent bullpen workload":null,!game.quality.lineups?"confirmed batting orders":null,!game.quality.weather?"official weather":null,!game.quality.parkSample?"reliable park sample":null].filter((item):item is string=>Boolean(item)),confidence=Math.max(25,100-game.uncertainty);
  return <section className="game-study" id="game-study" aria-labelledby="game-study-title"><header className="study-hero"><div><p className="eyebrow">SELECTED GAME STUDY</p><h2 id="game-study-title">{game.away.name} <span>at</span> {game.home.name}</h2><p>{time(game.startsAt)} · {game.venue} · {game.status}</p></div><div className="study-status"><strong>{confidence}%</strong><span>input confidence</span><em>RESEARCH MODEL</em></div></header><div className="study-warning"><strong>No certified betting recommendation</strong><span>The complete live model has not passed end-to-end prospective validation. Probabilities below are uncertainty-adjusted research estimates, not guarantees.</span></div><div className="study-clubs"><article><div><i>{game.away.abbreviation}</i><span><small>AWAY · {records?`${records.away.wins}-${records.away.losses}`:"record pending"}</small><strong>{game.away.name}</strong></span><b>{game.away.expectedRuns}</b></div><p><strong>{game.away.probablePitcher??"Starter TBD"}</strong>{game.away.starter?`${game.away.starter.era.toFixed(2)} ERA · ${game.away.starter.innings.toFixed(1)} IP · ${game.away.starter.expectedStrikeouts?.toFixed(1)??"—"} projected K`:"Official season line pending"}</p></article><article><div><i>{game.home.abbreviation}</i><span><small>HOME · {records?`${records.home.wins}-${records.home.losses}`:"record pending"}</small><strong>{game.home.name}</strong></span><b>{game.home.expectedRuns}</b></div><p><strong>{game.home.probablePitcher??"Starter TBD"}</strong>{game.home.starter?`${game.home.starter.era.toFixed(2)} ERA · ${game.home.starter.innings.toFixed(1)} IP · ${game.home.starter.expectedStrikeouts?.toFixed(1)??"—"} projected K`:"Official season line pending"}</p></article></div><div className="study-context"><article><small>EXPECTED SCORE</small><strong>{game.away.expectedRuns}–{game.home.expectedRuns}</strong><span>{game.total.expectedRuns} combined runs</span></article><article><small>PARK / WEATHER</small><strong>{game.park.factor.toFixed(3)} park factor</strong><span>{game.weather.temperature!=null?`${game.weather.temperature}°F · ${game.weather.condition??"condition pending"}`:"Weather pending"}</span></article><article><small>DATA COMPLETENESS</small><strong>{missing.length?`${missing.length} gaps` :"Core inputs present"}</strong><span>{missing.length?missing.join(" · "):"Still awaiting live-model validation"}</span></article></div><div className="study-body"><div><div className="study-section-title"><span><p className="eyebrow">ALL MODELED MARKETS</p><h3>Possible selections and why</h3></span><small>Displayed % includes an uncertainty penalty</small></div><div className="study-markets">{picks.sort((a,b)=>b.probability-a.probability).map(pick=><article key={pick.id}><header><span><small>{pick.market}</small><strong>{pick.selection}</strong></span><b>{(pick.probability*100).toFixed(1)}%</b></header><div className="probability-track"><i style={{width:`${pick.probability*100}%`}}/></div><p>{pick.explanation}</p><dl><div><dt>Raw model</dt><dd>{(pick.rawProbability*100).toFixed(1)}%</dd></div><div><dt>Conservative fair price</dt><dd>{pick.fairPrice}</dd></div><div><dt>Status</dt><dd>Unverified live stack</dd></div></dl><footer>{pick.inputNote}</footer></article>)}</div></div><aside className="study-reasons"><p className="eyebrow">WHAT MOVED THE MODEL</p><h3>Matchup factors</h3>{game.drivers.map((driver,index)=><div key={driver}><b>{index+1}</b><p>{driver}</p></div>)}<div className="study-limit"><strong>Known limitation</strong><p>{game.quality.blockingReasons.join(" · ")||"No blocking data gap reported."}</p></div></aside></div></section>;
}

function ShadowAudit({performance}:{performance:ProspectivePerformance|null}){
  return <section className="shadow-audit" id="shadow-audit"><header><div><p className="eyebrow">PHASE 1 · SHADOW MODE</p><h2>Frozen projection audit</h2><p>Every eligible pregame projection is now immutable, versioned and graded from official MLB finals. No wagering status is produced.</p></div><span>{performance?.issued??0} FROZEN</span></header>{performance?<><div className="audit-summary"><article><small>GRADED</small><strong>{performance.total.count}</strong><span>{performance.total.accuracy==null?"Awaiting finals":`${(performance.total.accuracy*100).toFixed(1)}% directional accuracy`}</span></article><article><small>BRIER SCORE</small><strong>{performance.total.brier?.toFixed(3)??"—"}</strong><span>Lower is better · probability quality</span></article><article><small>OPEN</small><strong>{performance.status.OPEN??0}</strong><span>Waiting for official final</span></article></div><div className="audit-tables"><div><h3>By market</h3><div className="audit-table"><div><span>Market</span><span>n</span><span>Accuracy</span><span>Brier</span></div>{performance.markets.map(row=><div key={row.market}><strong>{row.market.toUpperCase()}</strong><span>{row.count}</span><span>{row.accuracy==null?"—":`${(row.accuracy*100).toFixed(1)}%`}</span><span>{row.brier?.toFixed(3)??"—"}</span></div>)}</div></div><div><h3>By confidence band</h3><div className="audit-table"><div><span>Band</span><span>n</span><span>Accuracy</span><span>Brier</span></div>{performance.bands.map(row=><div key={row.label}><strong>{row.label}</strong><span>{row.count}</span><span>{row.accuracy==null?"—":`${(row.accuracy*100).toFixed(1)}%`}</span><span>{row.brier?.toFixed(3)??"—"}</span></div>)}</div></div></div><footer><strong>Activation remains locked.</strong><span>A market can advance only after sufficient frozen volume, stable calibration, and later—when odds are connected—positive closing-line value.</span></footer></>:<div className="board-empty">Shadow results are initializing. New projections will appear after eligible games are frozen and graded.</div>}</section>;
}

export function Dashboard() {
  const [date,setDate]=useState(()=>new Date().toISOString().slice(0,10));
  const [games,setGames]=useState<ProjectionGame[]>([]);
  const [selected,setSelected]=useState<number|null>(null);
  const [loading,setLoading]=useState(true);
  const [error,setError]=useState<string|null>(null);
  const [updated,setUpdated]=useState<string|null>(null);
  const [navOpen,setNavOpen]=useState(false);
  const [marketPrice,setMarketPrice]=useState("-110");
  const [oppositePrice,setOppositePrice]=useState("-110");
  const [marketMode,setMarketMode]=useState<"moneyline"|"over"|"under"|"f5"|"nrfi"|"yrfi"|"awayK"|"homeK"|"hit">("moneyline");
  const [propLine,setPropLine]=useState("5.5");
  const [selectedHitterId,setSelectedHitterId]=useState<number|null>(null);
  const [ownerKey,setOwnerKey]=useState("");
  const [ledger,setLedger]=useState<LedgerBet[]>([]);
  const [saving,setSaving]=useState(false);
  const [settling,setSettling]=useState(false);
  const [ledgerMessage,setLedgerMessage]=useState<string|null>(null);
  const [oddsFeed,setOddsFeed]=useState<OddsResponse|null>(null);
  const [oddsVault,setOddsVault]=useState<OddsVault|null>(null);
  const [sportsbook,setSportsbook]=useState("Sportsbook");
  const [snapshotMessage,setSnapshotMessage]=useState<string|null>(null);
  const [guideOpen,setGuideOpen]=useState(true);
  const [closingDrafts,setClosingDrafts]=useState<Record<string,{selected:string;opposite:string}>>({});
  const [bankroll,setBankroll]=useState("1000");
  const [backtest,setBacktest]=useState<Backtest|null>(null);
  const [prospective,setProspective]=useState<ProspectivePerformance|null>(null);
  const [model,setModel]=useState<ModelInfo|null>(null);
  const [dataHealth,setDataHealth]=useState<DataHealth|null>(null);
  const loadSequence=useRef(0);
  const active=useMemo(()=>games.find(game=>game.id===selected)??games[0]??null,[games,selected]);
  const pickBoard=useMemo(()=>dailyPicks(games),[games]);
  const activeOdds=useMemo(()=>active?oddsFeed?.games.find(game=>game.homeTeam===active.home.name&&game.awayTeam===active.away.name)??null:null,[active,oddsFeed]);
  const activeTotalLine=activeOdds?.total?.line??active?.total.line??8.5;
  const priced=useMemo(()=>{
    if(!active) return null;
    const favorite=active.home.winProbability>=active.away.winProbability?active.home:active.away;
    const f5Home=active.firstFive.homeWinProbability>=active.firstFive.awayWinProbability;
    const hitters=[...active.lineups.away,...active.lineups.home]; const hitter=hitters.find(player=>player.id===selectedHitterId)??hitters[0];
    const pitcher=marketMode==="awayK"?active.away:active.home; const kProbability=(marketMode==="awayK"||marketMode==="homeK")&&pitcher.starter?.expectedStrikeouts!=null?countOverProbability(pitcher.starter.expectedStrikeouts,Number(propLine)):null;
    const offeredTotal=activeTotalLine===active.total.line?{over:active.total.overProbability,under:active.total.underProbability,push:0}:projectScore(active.away.expectedRuns,active.home.expectedRuns,activeTotalLine);
    const market=marketMode==="hit"?hitter?.onePlusHitProbability==null?null:{name:`${hitter.name} 1+ hit`,probability:hitter.onePlusHitProbability,fairPrice:hitter.fairPrice??fairAmerican(hitter.onePlusHitProbability)}:marketMode==="awayK"||marketMode==="homeK"?kProbability==null?null:{name:`${pitcher.probablePitcher} over ${propLine} Ks`,probability:kProbability,fairPrice:fairAmerican(kProbability)}:marketMode==="over"?{name:`Over ${activeTotalLine}`,probability:offeredTotal.over,pushProbability:offeredTotal.push,fairPrice:fairAmerican(offeredTotal.over/(1-offeredTotal.push))}:marketMode==="under"?{name:`Under ${activeTotalLine}`,probability:offeredTotal.under,pushProbability:offeredTotal.push,fairPrice:fairAmerican(offeredTotal.under/(1-offeredTotal.push))}:marketMode==="f5"?{name:`${f5Home?active.home.name:active.away.name} F5 ML`,probability:f5Home?active.firstFive.homeWinProbability:active.firstFive.awayWinProbability,fairPrice:f5Home?active.firstFive.homeFairPrice:active.firstFive.awayFairPrice}:marketMode==="nrfi"?{name:"NRFI",probability:active.firstInning.nrfiProbability,fairPrice:active.firstInning.nrfiFairPrice}:marketMode==="yrfi"?{name:"YRFI",probability:active.firstInning.yrfiProbability,fairPrice:active.firstInning.yrfiFairPrice}:{name:`${favorite.name} moneyline`,probability:favorite.winProbability,fairPrice:favorite.fairPrice};
    if(!market)return null;
    const odds=Number(marketPrice);
    const decision=priceDecision(market.probability,odds,active.uncertainty/100,Number(oppositePrice),market.pushProbability??0);
    return decision?{market,odds,maxPlayableOdds:playablePriceThreshold(market.probability,Number(oppositePrice),active.uncertainty/100,market.pushProbability??0),...decision}:null;
  },[active,activeTotalLine,marketPrice,oppositePrice,marketMode,propLine,selectedHitterId]);
  const portfolioGate=useMemo(()=>{if(!active||!priced)return null;const moneylineHome=active.home.winProbability>=active.away.winProbability,firstFiveHome=active.firstFive.homeWinProbability>=active.firstFive.awayWinProbability,line=marketMode==="over"||marketMode==="under"?activeTotalLine:marketMode==="awayK"||marketMode==="homeK"?Number(propLine):null,selectionKey=marketMode==="moneyline"?(moneylineHome?"home":"away"):marketMode==="f5"?(firstFiveHome?"home":"away"):marketMode==="awayK"||marketMode==="homeK"?"over":marketMode==="hit"?"onePlus":marketMode;if(active.startsAt&&Date.now()>=Date.parse(active.startsAt))return{qualifies:false,reason:"Recommendations lock at scheduled first pitch.",dailyExposure:0,gameExposure:0};return portfolioDecision(ledger.filter(bet=>bet.status==="OPEN").map(bet=>({gameId:bet.game_id,gameDate:bet.game_date,market:bet.market,selectionKey:bet.selection_key,line:bet.line,stakeUnits:bet.stake_units})),{gameId:active.id,gameDate:date,market:marketMode,selectionKey,line,stakeUnits:priced.stakeFraction});},[active,activeTotalLine,priced,ledger,date,marketMode,propLine]);
  const ledgerPerformance=useMemo(()=>{const settled=ledger.filter(bet=>["WON","LOST","PUSH"].includes(bet.status)&&bet.profit_units!=null),summarize=(rows:LedgerBet[])=>{const stake=rows.reduce((sum,row)=>sum+row.stake_units,0),profit=rows.reduce((sum,row)=>sum+(row.profit_units??0),0),clvRows=rows.filter(row=>row.closing_line_value!=null);return{count:rows.length,wins:rows.filter(row=>row.status==="WON").length,losses:rows.filter(row=>row.status==="LOST").length,pushes:rows.filter(row=>row.status==="PUSH").length,stake,profit,roi:stake?profit/stake:null,clv:clvRows.length?clvRows.reduce((sum,row)=>sum+(row.closing_line_value??0),0)/clvRows.length:null};},markets=[...new Set(settled.map(bet=>bet.market))].map(market=>({market,...summarize(settled.filter(bet=>bet.market===market))}));return{total:summarize(settled),markets};},[ledger]);
  const load=useCallback(async()=>{ const sequence=++loadSequence.current; setLoading(true); setError(null); try { const yesterday=new Date(Date.now()-86400000).toISOString().slice(0,10); const through=date<yesterday?date:yesterday; const historyPromise=fetch(`/api/mlb/backtest?through=${through}`,{cache:"no-store"}); void historyPromise.then(async historyResponse=>{if(sequence===loadSequence.current&&historyResponse.ok)setBacktest(await historyResponse.json() as Backtest);}).catch(()=>{}); const [response,oddsResponse,vaultResponse]=await Promise.all([fetch(`/api/mlb/projections?date=${date}`,{cache:"no-store"}),fetch("/api/odds",{cache:"no-store"}),fetch("/api/odds-vault",{cache:"no-store"})]); const payload=await response.json() as ApiResponse; if(sequence!==loadSequence.current)return; if(!response.ok||payload.error) throw new Error(payload.error??"Unable to load projections"); setGames(payload.games);setModel(payload.model??null);setDataHealth(payload.dataHealth??null); setUpdated(payload.retrievedAt); setSelected(current=>payload.games.some(game=>game.id===current)?current:payload.games[0]?.id??null); void fetch("/api/mlb/forecast-performance",{cache:"no-store"}).then(async performanceResponse=>{if(sequence===loadSequence.current&&performanceResponse.ok)setProspective(await performanceResponse.json() as ProspectivePerformance);}).catch(()=>{}); if(oddsResponse.ok)setOddsFeed(await oddsResponse.json() as OddsResponse);if(vaultResponse.ok)setOddsVault(await vaultResponse.json() as OddsVault); } catch(reason) { if(sequence!==loadSequence.current)return; setGames([]);setModel(null);setDataHealth(null); setError(reason instanceof Error?reason.message:"Unable to load projections"); } finally { if(sequence===loadSequence.current)setLoading(false); } },[date]);
  useEffect(()=>{void load();},[load]);
  const loadLedger=useCallback(async(key:string,reconcile=false)=>{try{if(reconcile)await fetch("/api/ledger",{method:"PATCH",headers:{"content-type":"application/json"},body:JSON.stringify({ownerKey:key})});const response=await fetch(`/api/ledger?ownerKey=${encodeURIComponent(key)}`,{cache:"no-store"});if(response.ok){const payload=await response.json() as {bets:LedgerBet[]};setLedger(payload.bets);}}catch{/* Ledger status remains non-blocking. */}},[]);
  useEffect(()=>{let key=localStorage.getItem("baseline-ledger-key");if(!key){key=crypto.randomUUID();localStorage.setItem("baseline-ledger-key",key);}setOwnerKey(key);void loadLedger(key,true);},[loadLedger]);
  useEffect(()=>{setGuideOpen(localStorage.getItem("baseline-guide-dismissed")!=="yes");},[]);
  const dataGate=useMemo(()=>{if(!active)return{qualifies:false,reason:"Select a game."};const requiresBothStarters=!["hit","awayK","homeK"].includes(marketMode),validationKey=marketMode==="moneyline"?"moneyline":marketMode==="over"||marketMode==="under"?"total":marketMode==="f5"?"firstFive":marketMode==="nrfi"||marketMode==="yrfi"?"firstInning":marketMode==="awayK"||marketMode==="homeK"?"pitcherStrikeouts":"hitterHits",marketValidated=active.quality.validatedMarkets[validationKey];const hitters=[...active.lineups.away,...active.lineups.home],selectedHitter=hitters.find(hitter=>hitter.id===selectedHitterId)??hitters[0];const reasons=[!marketValidated?"This probability model has not passed market-specific walk-forward validation.":null,!active.quality.teamRecords?"Both team season records are required.":null,requiresBothStarters&&!active.quality.starterStats?"Both probable starters need official season statistics.":null,marketMode==="awayK"&&!active.quality.opponentStrikeouts?"Opponent team strikeout rate is required.":null,marketMode==="homeK"&&!active.quality.opponentStrikeouts?"Opponent team strikeout rate is required.":null,marketMode==="awayK"&&!active.quality.awayStarter?"The away starter needs an official season stat line.":null,marketMode==="homeK"&&!active.quality.homeStarter?"The home starter needs an official season stat line.":null,marketMode==="hit"&&!active.quality.lineups?"Confirmed batting orders are required for hit props.":null,marketMode==="hit"&&!selectedHitter?.platoonAdjusted?"A verified split against the opposing starter’s hand is required.":null].filter((reason):reason is string=>Boolean(reason));return{qualifies:reasons.length===0,reason:reasons[0]??"Required model inputs and market validation are available."};},[active,marketMode,selectedHitterId]);
  const saveRecommendation=useCallback(async()=>{if(!active||!priced?.qualifies||!dataGate.qualifies||!portfolioGate?.qualifies||!ownerKey)return;setSaving(true);setLedgerMessage(null);const line=marketMode==="over"||marketMode==="under"?activeTotalLine:marketMode==="awayK"||marketMode==="homeK"?Number(propLine):null;const moneylineHome=active.home.winProbability>=active.away.winProbability,firstFiveHome=active.firstFive.homeWinProbability>=active.firstFive.awayWinProbability,hitters=[...active.lineups.away,...active.lineups.home],hitter=hitters.find(player=>player.id===selectedHitterId)??hitters[0];const selectionKey=marketMode==="moneyline"?(moneylineHome?"home":"away"):marketMode==="f5"?(firstFiveHome?"home":"away"):marketMode==="awayK"||marketMode==="homeK"?"over":marketMode==="hit"?"onePlus":marketMode;const subjectId=marketMode==="awayK"?active.away.starter?.playerId??null:marketMode==="homeK"?active.home.starter?.playerId??null:marketMode==="hit"?hitter?.id??null:null;try{const response=await fetch("/api/ledger",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({ownerKey,gameId:active.id,gameDate:date,startsAt:active.startsAt,matchup:`${active.away.abbreviation} @ ${active.home.abbreviation}`,market:marketMode,selection:priced.market.name,selectionKey,subjectId,line,americanOdds:Number(marketPrice),oppositeOdds:Number(oppositePrice),modelProbability:priced.market.probability,marketProbability:priced.marketProbability,edge:priced.edge,expectedValue:priced.expectedValue,stakeUnits:priced.stakeFraction})});const payload=await response.json() as {error?:string};if(!response.ok)throw new Error(payload.error??"Unable to save");setLedgerMessage("Recommendation saved to your ledger.");await loadLedger(ownerKey);}catch(reason){setLedgerMessage(reason instanceof Error?reason.message:"Unable to save recommendation");}finally{setSaving(false);}},[active,activeTotalLine,priced,ownerKey,marketMode,propLine,date,marketPrice,oppositePrice,selectedHitterId,loadLedger,portfolioGate,dataGate]);
  const removeBet=useCallback(async(id:string)=>{if(!ownerKey)return;await fetch(`/api/ledger?ownerKey=${encodeURIComponent(ownerKey)}&id=${encodeURIComponent(id)}`,{method:"DELETE"});await loadLedger(ownerKey);},[ownerKey,loadLedger]);
  const settleLedger=useCallback(async()=>{if(!ownerKey)return;setSettling(true);setLedgerMessage(null);try{const response=await fetch("/api/ledger",{method:"PATCH",headers:{"content-type":"application/json"},body:JSON.stringify({ownerKey})});const payload=await response.json() as {settled?:number;error?:string};if(!response.ok)throw new Error(payload.error??"Unable to settle");setLedgerMessage(`${payload.settled??0} final recommendation${payload.settled===1?"":"s"} settled.`);await loadLedger(ownerKey);}catch(reason){setLedgerMessage(reason instanceof Error?reason.message:"Unable to settle recommendations");}finally{setSettling(false);}},[ownerKey,loadLedger]);
  const saveClosingLine=useCallback(async(id:string)=>{if(!ownerKey)return;const draft=closingDrafts[id];if(!draft)return;setLedgerMessage(null);try{const response=await fetch("/api/ledger",{method:"PUT",headers:{"content-type":"application/json"},body:JSON.stringify({ownerKey,id,closingOdds:Number(draft.selected),closingOppositeOdds:Number(draft.opposite)})});const payload=await response.json() as {error?:string};if(!response.ok)throw new Error(payload.error??"Unable to save closing line");setLedgerMessage("Closing line saved. CLV now uses two-sided no-vig probabilities.");await loadLedger(ownerKey);}catch(reason){setLedgerMessage(reason instanceof Error?reason.message:"Unable to save closing line");}},[ownerKey,closingDrafts,loadLedger]);
  const useConsensus=useCallback(()=>{if(!active||!activeOdds)return;let selected:ConsensusSide=null,opposite:ConsensusSide=null;if(marketMode==="moneyline"){const homeFavorite=active.home.winProbability>=active.away.winProbability;selected=homeFavorite?activeOdds.moneyline.home:activeOdds.moneyline.away;opposite=homeFavorite?activeOdds.moneyline.away:activeOdds.moneyline.home;}else if(marketMode==="over"||marketMode==="under"){selected=marketMode==="over"?activeOdds.total?.over??null:activeOdds.total?.under??null;opposite=marketMode==="over"?activeOdds.total?.under??null:activeOdds.total?.over??null;}if(selected&&selected.pairedOppositeAmerican!=null){setMarketPrice(String(selected.bestAmerican));setOppositePrice(String(selected.pairedOppositeAmerican));}},[active,activeOdds,marketMode]);
  const saveMarketSnapshot=useCallback(async()=>{if(!active||!priced)return;setSnapshotMessage(null);const line=marketMode==="over"||marketMode==="under"?activeTotalLine:marketMode==="awayK"||marketMode==="homeK"?Number(propLine):null;try{const response=await fetch("/api/odds-vault",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({gameId:active.id,gameDate:date,startsAt:active.startsAt,awayTeam:active.away.name,homeTeam:active.home.name,market:marketMode,selection:priced.market.name,oppositeSelection:`Opposite of ${priced.market.name}`,line,selectedOdds:Number(marketPrice),oppositeOdds:Number(oppositePrice),sportsbook})});const payload=await response.json() as {error?:string};if(!response.ok)throw new Error(payload.error??"Unable to save prices");setSnapshotMessage("Two-sided market snapshot saved.");const vaultResponse=await fetch("/api/odds-vault",{cache:"no-store"});if(vaultResponse.ok)setOddsVault(await vaultResponse.json() as OddsVault);}catch(reason){setSnapshotMessage(reason instanceof Error?reason.message:"Unable to save prices");}},[active,priced,marketMode,activeTotalLine,propLine,date,marketPrice,oppositePrice,sportsbook]);
  const canSave=false; // Phase 1 shadow mode: no model output can be saved as a wagering recommendation.

  return <main className="app-shell">
    <aside className={`sidebar ${navOpen?"open":""}`}><div className="logo"><span className="logo-mark">B</span><span>BASELINE</span></div><nav aria-label="Primary navigation"><a className="nav-link active" href="#slate">Today</a><button className="nav-link nav-button" onClick={()=>setGuideOpen(true)}>How to use</button><a className="nav-link" href="#models">Models</a><a className="nav-link" href="#data">Data health</a><a className="nav-link" href="#performance">Performance</a></nav><div className="sidebar-foot"><div className="system-dot"><i/> Experimental model online</div><div className="user-chip"><span>DB</span><small>Daniel’s workspace</small></div></div></aside>
    <section className="workspace"><header className="topbar"><button className="menu" onClick={()=>setNavOpen(!navOpen)} aria-label="Toggle navigation">☰</button><div><p className="eyebrow">MLB ANALYSIS WORKSPACE</p><h1>Daily slate</h1></div><div className="top-actions"><button className="ghost-button" onClick={()=>setGuideOpen(true)}>How it works</button><button className="primary-button" onClick={()=>void load()} disabled={loading}>↻ {loading?"Refreshing…":"Refresh data"}</button></div></header>
      <div className="notice" role="status"><span>i</span><div><strong>Phase 1 shadow mode is active</strong><p>Pregame projections are frozen and graded automatically. The app currently issues no bets or validated picks.</p></div></div>
      {guideOpen&&<section className="guide-panel" aria-labelledby="guide-title"><div className="guide-head"><div><p className="eyebrow">GETTING STARTED</p><h2 id="guide-title">From matchup to tracked decision</h2></div><button onClick={()=>{setGuideOpen(false);localStorage.setItem("baseline-guide-dismissed","yes");}} aria-label="Dismiss getting started guide">×</button></div><div className="guide-steps"><article><b>1</b><div><strong>Choose a game</strong><p>Select a date and matchup. Check starters, lineups, model uncertainty, and the explanation—not only the headline probability.</p></div></article><article><b>2</b><div><strong>Choose a market</strong><p>ML means game winner. F5 is the first five innings. NRFI means no run in the first inning; YRFI means at least one run.</p></div></article><article><b>3</b><div><strong>Verify both prices</strong><p>Enter the selected and opposite sportsbook prices. Baseline removes the bookmaker margin and recommends only when every risk gate clears.</p></div></article><article><b>4</b><div><strong>Track, close, settle</strong><p>Save qualifying decisions before first pitch. The ledger blocks duplicates and caps exposure at 1% per game and 2% per day; capture closing prices, then settle results.</p></div></article></div><p className="guide-note"><strong>CLV</strong> is closing-line value: positive CLV means your saved price implied a lower fair probability than the final market price after removing vig.<br/><strong>Unit convention:</strong> 1u equals 1% of bankroll.</p></section>}
      <section className="live-slate"><div className="section-head live-head"><div><p className="eyebrow">OFFICIAL SCHEDULE + MODEL</p><h2>Games for {date}</h2></div><div className="date-controls"><button onClick={()=>setDate(shiftDate(date,-1))} aria-label="Previous day">←</button><input type="date" value={date} onChange={event=>setDate(event.target.value)} aria-label="Schedule date"/><button onClick={()=>setDate(shiftDate(date,1))} aria-label="Next day">→</button></div></div>
        {loading?<div className="slate-state"><i className="loading-mark"/>Loading MLB data and calculating games…</div>:error?<div className="slate-state error"><strong>Live model unavailable</strong><span>{error}</span><button onClick={()=>void load()}>Try again</button></div>:games.length===0?<div className="slate-state">No MLB games are scheduled for this date.</div>:<div className="game-strip">{games.map(game=><button className={`game-tile game-button ${selected===game.id?"active":""}`} key={game.id} onClick={()=>setSelected(game.id)}><div className="game-status"><span>{game.status}</span><time>{time(game.startsAt)}</time></div><div className="club-row"><strong>{game.away.abbreviation}</strong><span>{game.away.name}</span><em>{game.away.expectedRuns}</em></div><div className="club-row"><strong>{game.home.abbreviation}</strong><span>{game.home.name}</span><em>{game.home.expectedRuns}</em></div><div className="pitchers"><span>{game.away.probablePitcher??"Starter TBD"}</span><b>vs</b><span>{game.home.probablePitcher??"Starter TBD"}</span></div><small>{game.venue}</small></button>)}</div>}
        <div className="live-foot"><span><i/> MLB Stats API · Run + Starter Baseline v0.2</span><span>{updated?`Updated ${new Date(updated).toLocaleTimeString([],{hour:"numeric",minute:"2-digit"})}`:"Waiting for source"}</span></div></section>
      <section className="hero-grid" id="slate"><article className="slate-card"><div className="section-head"><div><p className="eyebrow">EXPERIMENTAL BASELINE</p><h2>Model leans—not recommendations</h2></div><span className="model-badge">{model?.calibrated?"BASE CALIBRATED":"CALIBRATION PENDING"}</span></div><div className="pick-table"><div className="table-row table-header"><span>Game / lean</span><span>Win prob.</span><span>Fair line</span><span>Exp. total</span><span>Action</span></div>{games.map(game=>{const side=game.home.winProbability>=game.away.winProbability?game.home:game.away;return <button className={`table-row ${selected===game.id?"selected":""}`} key={game.id} onClick={()=>setSelected(game.id)}><span className="selection"><i className="team-badge navy">{side.abbreviation}</i><span><strong>{side.name}</strong><small>{game.away.abbreviation} @ {game.home.abbreviation}</small></span></span><span className="mono">{(side.winProbability*100).toFixed(1)}%</span><span className="mono">{side.fairPrice}</span><span className="mono">{game.total.expectedRuns}</span><span className="no-bet">NO BET</span></button>})}</div><div className="table-foot"><span><i className="quality-dot"/> Team scoring, prevention, home field, score distribution</span><span>Market odds required</span></div></article>
        <aside className="explain-card">{active?<><div className="explain-top"><div><p className="eyebrow">MATCHUP + PRICE LAB</p><h3>{active.away.abbreviation} at {active.home.abbreviation}</h3><p>{time(active.startsAt)} · {active.venue}</p></div><Ring value={100-active.uncertainty}/></div><div className="price-grid"><div><small>AWAY WIN</small><strong>{(active.away.winProbability*100).toFixed(1)}%</strong></div><div><small>HOME WIN</small><strong>{(active.home.winProbability*100).toFixed(1)}%</strong></div><div><small>EXPECTED SCORE</small><strong>{active.away.expectedRuns}–{active.home.expectedRuns}</strong></div></div><div className="environment-grid"><div><small>PARK FACTOR</small><strong>{active.park.factor.toFixed(3)}</strong><span>{active.park.priorGames} prior games</span></div><div><small>OFFICIAL WEATHER</small><strong>{active.weather.temperature!=null?`${active.weather.temperature}°F`:"Pending"}</strong><span>{active.weather.condition??active.weather.roof??"Not posted"}</span></div><div><small>WIND / ROOF</small><strong>{active.weather.roof??"Open air"}</strong><span>{active.weather.wind??"Not posted"}</span></div></div><div className="starter-grid"><div><small>{active.away.abbreviation} STARTER</small><strong>{active.away.probablePitcher??"TBD"}</strong><span>{active.away.starter?`${active.away.starter.era.toFixed(2)} ERA · ${active.away.starter.expectedStrikeouts?.toFixed(1)??"—"} proj. K · ${active.away.opponentStrikeoutRate==null?"—":(active.away.opponentStrikeoutRate*100).toFixed(1)+"% opp K"}`:"Season stats pending"}</span></div><div><small>{active.home.abbreviation} STARTER</small><strong>{active.home.probablePitcher??"TBD"}</strong><span>{active.home.starter?`${active.home.starter.era.toFixed(2)} ERA · ${active.home.starter.expectedStrikeouts?.toFixed(1)??"—"} proj. K · ${active.home.opponentStrikeoutRate==null?"—":(active.home.opponentStrikeoutRate*100).toFixed(1)+"% opp K"}`:"Season stats pending"}</span></div></div><div className="bullpen-grid"><div><small>{active.away.abbreviation} BULLPEN · LAST 2 DAYS</small><strong>{active.away.bullpen.recentPitches} relief pitches</strong><span>{active.away.bullpen.taxedRelievers} taxed arms · +{active.away.bullpen.runAdjustment.toFixed(3)} opponent runs</span></div><div><small>{active.home.abbreviation} BULLPEN · LAST 2 DAYS</small><strong>{active.home.bullpen.recentPitches} relief pitches</strong><span>{active.home.bullpen.taxedRelievers} taxed arms · +{active.home.bullpen.runAdjustment.toFixed(3)} opponent runs</span></div></div><div className="driver-list">{active.drivers.map((driver,index)=><div key={driver}><span>{index+1}</span><div><strong>{driver.startsWith("Park factor")?"Park environment":driver.startsWith("Official game weather")?"Weather context":driver.startsWith("Team baseline")?"Calibration":driver.startsWith("Opponent K tendency")?"Opponent strikeouts":driver.startsWith("Bullpen workload")?"Bullpen workload":driver.startsWith("Hitter platoon context")?"Hitter platoon splits":index===2?"League environment":index===3?"Starter adjustment":"Season scoring"}</strong><p>{driver}</p></div></div>)}</div><div className="odds-lab"><div className="market-tabs multi props" role="group" aria-label="Price lab market"><button className={marketMode==="moneyline"?"active":""} onClick={()=>setMarketMode("moneyline")}>ML</button><button className={marketMode==="over"?"active":""} onClick={()=>setMarketMode("over")}>Over</button><button className={marketMode==="under"?"active":""} onClick={()=>setMarketMode("under")}>Under</button><button className={marketMode==="f5"?"active":""} onClick={()=>setMarketMode("f5")}>F5 ML</button><button className={marketMode==="nrfi"?"active":""} onClick={()=>setMarketMode("nrfi")}>NRFI</button><button className={marketMode==="yrfi"?"active":""} onClick={()=>setMarketMode("yrfi")}>YRFI</button><button className={marketMode==="awayK"?"active":""} onClick={()=>setMarketMode("awayK")}>{active.away.abbreviation} K</button><button className={marketMode==="homeK"?"active":""} onClick={()=>setMarketMode("homeK")}>{active.home.abbreviation} K</button><button className={marketMode==="hit"?"active":""} onClick={()=>setMarketMode("hit")}>1+ Hit</button></div><div className="odds-title"><div><small>TWO-SIDED MARKET CHECK</small><strong>{priced?.market.name??"Prop unavailable"}</strong></div><span>{priced?`Fair ${priced.market.fairPrice} · Play to ${priced.maxPlayableOdds==null?"—":priced.maxPlayableOdds>0?"+"+priced.maxPlayableOdds:priced.maxPlayableOdds} or better`:"No projection"}</span></div>{(marketMode==="awayK"||marketMode==="homeK")&&<label className="prop-line">Strikeout line<input type="number" min="0.5" max="15.5" step="1" value={propLine} onChange={event=>setPropLine(event.target.value)} aria-label="Strikeout prop line"/></label>}{marketMode==="hit"&&<label className="hitter-select">Confirmed hitter<select value={selectedHitterId??[...active.lineups.away,...active.lineups.home][0]?.id??""} onChange={event=>setSelectedHitterId(Number(event.target.value))}>{active.lineups.away.map(player=><option key={player.id} value={player.id}>{active.away.abbreviation} #{player.battingOrder} · {player.name} · vs {player.opposingHand??"?"} ({player.platoonAtBats??0} AB)</option>)}{active.lineups.home.map(player=><option key={player.id} value={player.id}>{active.home.abbreviation} #{player.battingOrder} · {player.name} · vs {player.opposingHand??"?"} ({player.platoonAtBats??0} AB)</option>)}</select></label>}<div className="micro-market"><span>F5 total {active.firstFive.expectedRuns}</span><span>F5 push {(active.firstFive.pushProbability*100).toFixed(1)}%</span><span>Lineups {active.lineups.confirmed?"confirmed":"pending"}</span><span>Bullpen {active.quality.bullpen?"current":"pending"}</span><span>Opp. K {active.quality.opponentStrikeouts?"current":"pending"}</span><span>Platoon {active.quality.platoon?"complete":"partial"}</span></div><div className="odds-inputs three"><label>Selection odds<input inputMode="numeric" value={marketPrice} onChange={event=>setMarketPrice(event.target.value)} aria-label="Selected American odds"/></label><label>Opposite odds<input inputMode="numeric" value={oppositePrice} onChange={event=>setOppositePrice(event.target.value)} aria-label="Opposing American odds"/></label><label>Bankroll ($)<input inputMode="decimal" value={bankroll} onChange={event=>setBankroll(event.target.value)} aria-label="Bankroll in dollars"/></label></div>{priced?<div className={`decision ${priced.qualifies?"qualifies":"pass"}`}><div><small>NO-VIG MARKET</small><strong>{(priced.marketProbability*100).toFixed(1)}%</strong></div><div><small>MODEL EDGE</small><strong>{priced.edge>=0?"+":""}{(priced.edge*100).toFixed(1)}%</strong></div><div><small>EXPECTED ROI</small><strong>{priced.expectedValue>=0?"+":""}{(priced.expectedValue*100).toFixed(1)}%</strong></div><div><small>MAX STAKE</small><strong>{priced.qualifies?`$${(Number(bankroll||0)*priced.stakeFraction).toFixed(2)}`:"$0"}</strong></div><p>{priced.qualifies?"Price passes the no-vig edge, positive-EV and uncertainty gates. Stake is capped at 0.5% of bankroll.":"PASS — this price does not clear every safety gate. No wager recommended."}</p></div>:<p className="input-help">This market needs confirmed player statistics and both sportsbook prices.</p>}</div><div className="caution"><span>!</span><p><strong>Experimental only</strong>Hitter props require confirmed batting orders; season hit rate and handedness splits are regressed, capped, and disclosed per player.</p></div></>:<div className="slate-state">Select a game to inspect the model.</div>}</aside></section>
      <div className={`consensus-strip ${oddsFeed?.configured?"connected":"manual"}`}><div><strong>{oddsFeed?.configured?"Automatic consensus connected":"Manual odds mode"}</strong><span>{oddsFeed?.configured?`${activeOdds?.bookmakers??0} books matched this game · ${oddsFeed.provider}`:oddsFeed?.message??"No automatic odds provider is configured."}</span></div><button onClick={useConsensus} disabled={!activeOdds||!(marketMode==="moneyline"||marketMode==="over"||marketMode==="under")}>Use best paired book</button></div>
      <section className="odds-vault" id="odds-vault"><div><p className="eyebrow">PHASE 2 · NO-COST MARKET DATA</p><h2>Odds history vault</h2><span>{oddsVault?.summary.observations??0} prices stored across {oddsVault?.summary.games??0} games · $0 data plan</span></div><div className="vault-source"><strong>Free historical provider</strong><span>OddsPapi · coverage from Jan 2026</span><em className={oddsVault?.providers.oddsPapi.configured?"ready":"waiting"}>{oddsVault?.providers.oddsPapi.configured?"CONNECTED":"FREE KEY NEEDED"}</em></div><div className="vault-capture"><label>Sportsbook<input value={sportsbook} maxLength={80} onChange={event=>setSportsbook(event.target.value)} aria-label="Sportsbook source"/></label><button onClick={()=>void saveMarketSnapshot()} disabled={!active||!priced}>Save current two-sided prices</button>{snapshotMessage&&<small>{snapshotMessage}</small>}</div></section>
      <div className="save-strip locked"><div><strong>Shadow mode — wagering actions are disabled</strong><span>Use the price lab for research only. Activation remains locked until the frozen live record meets the required volume, calibration and market-value gates.</span></div><button disabled>Research only</button></div>
      <section className="metric-row" id="performance"><article><div><p className="eyebrow">WALK-FORWARD ACCURACY</p><strong>{backtest?.metrics.accuracy!=null?`${(backtest.metrics.accuracy*100).toFixed(1)}%`:"—"}</strong></div><small>{backtest?.metrics.count??0} out-of-sample games</small></article><article><div><p className="eyebrow">BRIER SCORE</p><strong>{(backtest?.calibratedMetrics?.selectedBrier??backtest?.metrics.brier)?.toFixed(3)??"—"}</strong></div><small>{backtest?.calibratedMetrics?`${backtest.calibratedMetrics.selectedMethod==="identity"?"Identity verified":"Platt calibrated"} · ECE ${(backtest.calibratedMetrics.rawEce*100).toFixed(1)}%`:"Raw · calibration needs 200 predictions"}</small></article><article><div><p className="eyebrow">TOTAL RUN MAE</p><strong>{backtest?.metrics.totalMae?.toFixed(2)??"—"}</strong></div><small>Average absolute runs error</small></article><article><div><p className="eyebrow">AVERAGE CLV</p><strong>{ledger.some(bet=>bet.closing_line_value!=null)?`${((ledger.reduce((sum,bet)=>sum+(bet.closing_line_value??0),0)/ledger.filter(bet=>bet.closing_line_value!=null).length)*100).toFixed(1)}%`:"—"}</strong></div><small>No-vig probability at close versus saved price</small></article><article><div><p className="eyebrow">REALIZED ROI</p><strong>{ledgerPerformance.total.roi==null?"—":`${ledgerPerformance.total.roi>=0?"+":""}${(ledgerPerformance.total.roi*100).toFixed(1)}%`}</strong></div><small>{ledgerPerformance.total.wins}W · {ledgerPerformance.total.losses}L · {ledgerPerformance.total.pushes}P · {ledgerPerformance.total.profit>=0?"+":""}{(ledgerPerformance.total.profit*100).toFixed(2)}u</small></article><article><div><p className="eyebrow">OPEN EXPOSURE</p><strong>{(ledger.filter(bet=>bet.status==="OPEN").reduce((sum,bet)=>sum+bet.stake_units,0)*100).toFixed(2)}u</strong></div><span className="exposure">{ledger.some(bet=>bet.status==="OPEN")?"TRACKED":"SAFE"}</span><small>{ledger.filter(bet=>bet.status==="OPEN").length} open recommendations</small></article></section>
      {prospective&&<section className="prospective-panel"><div className="section-head"><div><p className="eyebrow">PROSPECTIVE MODEL RECORD</p><h2>Frozen before first pitch, graded from official finals</h2></div><span className="model-badge">{prospective.issued} ISSUED</span></div><div className="prospective-grid"><article><small>ALL GRADED</small><strong>{prospective.total.count}</strong><span>{prospective.total.accuracy==null?"Awaiting finals":`${(prospective.total.accuracy*100).toFixed(1)}% accuracy · Brier ${prospective.total.brier?.toFixed(3)}`}</span></article>{prospective.markets.map(row=><article key={row.market}><small>{row.market.toUpperCase()}</small><strong>{row.count}</strong><span>{row.accuracy==null?"Awaiting finals":`${(row.accuracy*100).toFixed(1)}% · Brier ${row.brier?.toFixed(3)}`}</span></article>)}</div><div className="performance-foot"><span>{prospective.status.OPEN??0} open · {prospective.status.PUSH??0} pushes · {prospective.status.VOID??0} voids</span><span>First eligible snapshot is immutable; later refreshes cannot rewrite it</span></div></section>}
      {backtest&&<section className="performance-panel"><div className="section-head"><div><p className="eyebrow">HONEST HISTORICAL VALIDATION</p><h2>Calibration by predicted home-win probability</h2></div><span className="model-badge">THROUGH {backtest.through}</span></div><div className="calibration-grid">{backtest.calibration.map(bucket=><div className="calibration-row" key={bucket.low}><span>{Math.round(bucket.low*100)}–{Math.round(bucket.high*100)}%</span><div className="calibration-track"><i style={{width:`${(bucket.predicted??0)*100}%`}}/><b style={{left:`${(bucket.actual??0)*100}%`}}/></div><strong>{bucket.count?`${((bucket.actual??0)*100).toFixed(0)}% actual`:"No games"}</strong><small>n={bucket.count}</small></div>)}</div><div className="performance-foot"><span>{backtest.gamesIngested} final games ingested from MLB</span><span>{backtest.calibratedMetrics?`${backtest.calibratedMetrics.count} leakage-safe calibration tests · selected ${backtest.calibratedMetrics.selectedMethod} · log loss ${backtest.calibratedMetrics.selectedLogLoss.toFixed(3)}`:"Expanding window · no future games used"}</span></div></section>}
      {backtest?.marketMetrics&&<section className="market-validation"><div className="section-head"><div><p className="eyebrow">MARKET-BY-MARKET BACKTEST</p><h2>Out-of-sample validation coverage</h2></div><span className="model-badge">NO MARKET ODDS</span></div><div className="validation-cards">{([["Moneyline",backtest.marketMetrics.moneyline,backtest.calibratedMetrics],["Total over 8.5",backtest.marketMetrics.totalOver85,backtest.marketCalibratedMetrics.totalOver85],["F5 home ML",backtest.marketMetrics.firstFiveHome,backtest.marketCalibratedMetrics.firstFiveHome],["NRFI",backtest.marketMetrics.nrfi,backtest.marketCalibratedMetrics.nrfi]] as Array<[string,BacktestMarketMetric,CalibrationMetrics|null]>).map(([label,metric,calibration])=><article key={label}><small>{label}</small><strong>{metric.accuracy==null?"—":(metric.accuracy*100).toFixed(1)+"%"}</strong><span>Accuracy · {calibration?.selectedMethod==="regularized-platt"?"Platt selected":calibration?.verified?"Identity verified":"Calibration pending"}</span><div><b>Brier {(calibration?.selectedBrier??metric.brier)?.toFixed(3)??"—"}</b><em>n={metric.count}</em></div></article>)}</div><p className="validation-note">Each prediction is generated before that game updates team or inning-share history. These scores validate model probabilities; they do not represent betting ROI because historical sportsbook prices are not included.</p></section>}
      <section className="ledger-panel"><div className="section-head"><div><p className="eyebrow">DURABLE RECOMMENDATION LEDGER</p><h2>Saved decisions</h2></div><div className="ledger-actions"><span className="model-badge">{ledger.length} RECORDS</span><button onClick={()=>void settleLedger()} disabled={settling||!ledger.some(bet=>bet.status==="OPEN")}>{settling?"Checking…":"Settle final games"}</button></div></div>{ledger.length?<div className="ledger-list">{ledger.map(bet=>{const closeState=closingWindow(bet.starts_at),closeLocked=!closeState.open,started=Boolean(bet.starts_at&&Date.now()>=new Date(bet.starts_at).getTime());return <div className="ledger-entry" key={bet.id}><div className="ledger-row"><span className={`ledger-status ${bet.status.toLowerCase()}`}>{bet.status}</span><div><strong>{bet.selection}</strong><small>{bet.matchup} · {bet.game_date} · play to {bet.max_playable_odds==null?"—":bet.max_playable_odds>0?"+"+bet.max_playable_odds:bet.max_playable_odds}</small></div><span>{bet.american_odds>0?"+":""}{bet.american_odds}</span><span className="ledger-edge">+{(bet.edge*100).toFixed(1)}%</span><span>{(bet.stake_units*100).toFixed(2)}u</span>{bet.status==="OPEN"?<button onClick={()=>void removeBet(bet.id)} disabled={started} title={started?"Locked after first pitch":undefined} aria-label={`Remove ${bet.selection}`}>Remove</button>:<strong>{bet.profit_units==null?"—":`${bet.profit_units>0?"+":""}${(bet.profit_units*100).toFixed(2)}u`}</strong>}</div><div className="closing-row"><div><strong>{bet.closing_line_value!=null?"Closing line captured":closeLocked?"Closing line locked":"Capture closing market"}</strong><small>{bet.closing_line_value!=null?`CLV ${bet.closing_line_value>=0?"+":""}${(bet.closing_line_value*100).toFixed(1)}% · close ${bet.closing_odds&&bet.closing_odds>0?"+":""}${bet.closing_odds}`:!closeState.open?closeState.reason:"Enter both sides near first pitch for valid no-vig CLV."}</small></div><label>Selection<input inputMode="numeric" placeholder="-110" disabled={closeLocked} value={closingDrafts[bet.id]?.selected??""} onChange={event=>setClosingDrafts(current=>({...current,[bet.id]:{selected:event.target.value,opposite:current[bet.id]?.opposite??""}}))}/></label><label>Opposite<input inputMode="numeric" placeholder="-110" disabled={closeLocked} value={closingDrafts[bet.id]?.opposite??""} onChange={event=>setClosingDrafts(current=>({...current,[bet.id]:{selected:current[bet.id]?.selected??"",opposite:event.target.value}}))}/></label><button onClick={()=>void saveClosingLine(bet.id)} disabled={closeLocked||!closingDrafts[bet.id]?.selected||!closingDrafts[bet.id]?.opposite}>Save close</button></div></div>})}</div>:<div className="slate-state">No saved recommendations yet. Only decisions that clear every gate can enter the ledger.</div>}</section>
      <section className="market-performance"><div className="section-head"><div><p className="eyebrow">REALIZED PERFORMANCE</p><h2>Results by market</h2></div><span className="model-badge">SETTLED ONLY</span></div>{ledgerPerformance.markets.length?<div className="market-performance-table"><div className="market-performance-row header"><span>Market</span><span>Record</span><span>Staked</span><span>Profit</span><span>ROI</span><span>Avg. CLV</span></div>{ledgerPerformance.markets.map(row=><div className="market-performance-row" key={row.market}><strong>{row.market.toUpperCase()}</strong><span>{row.wins}-{row.losses}-{row.pushes}</span><span>{(row.stake*100).toFixed(2)}u</span><span className={row.profit>=0?"positive":"negative"}>{row.profit>=0?"+":""}{(row.profit*100).toFixed(2)}u</span><span>{row.roi==null?"—":`${row.roi>=0?"+":""}${(row.roi*100).toFixed(1)}%`}</span><span>{row.clv==null?"—":`${row.clv>=0?"+":""}${(row.clv*100).toFixed(1)}%`}</span></div>)}</div>:<div className="performance-empty">Market-level ROI and CLV will appear after tracked recommendations settle.</div>}</section>
      <section className="data-health-panel" id="data"><div className="section-head"><div><p className="eyebrow">DATA QUALITY</p><h2>Source coverage for this slate</h2></div><span className={`health-score ${(dataHealth?.score??0)>=90?"healthy":(dataHealth?.score??0)>=70?"review":"limited"}`}>{dataHealth?.score??"—"}/100</span></div>{dataHealth?<div className="coverage-grid">{([["Teams",dataHealth.coverage.teams],["Bullpen workload",dataHealth.coverage.bullpens],["Starter stats",dataHealth.coverage.starters],["Confirmed lineups",dataHealth.coverage.lineups],["Hitter stats",dataHealth.coverage.hitters],["Weather",dataHealth.coverage.weather],["Park samples",dataHealth.coverage.parks],["Opponent K rates",dataHealth.coverage.opponentStrikeouts],["Hitter platoon splits",dataHealth.coverage.platoonSplits],["Roster statuses",dataHealth.coverage.rosterStatuses]] as Array<[string,Coverage]>).map(([label,item])=>{const ratio=item.expected?item.available/item.expected:0;return <div className="coverage-row" key={label}><div><strong>{label}</strong><span>{item.available} / {item.expected}</span></div><div className="coverage-track"><i style={{width:`${Math.min(100,ratio*100)}%`}}/></div></div>})}</div>:<div className="slate-state">Waiting for source diagnostics.</div>}<div className="data-health-foot"><span>Feature cutoff {dataHealth?.featureCutoff??"—"}</span><span>{dataHealth?.historicalFinals??0} historical finals</span><span>{dataHealth?.calibrated?"Calibration verified":"Calibration pending"}</span></div></section>
      <section className="lower-grid"><article className="panel" id="models"><div className="section-head"><div><p className="eyebrow">MODEL CONTROL</p><h2>What is modeled now</h2></div></div><div className="check-list"><div><span className="check-icon good">✓</span><div><strong>Time-safe season baselines</strong><p>Runs scored and allowed through the selected season</p></div><em>ACTIVE</em></div><div><span className="check-icon good">✓</span><div><strong>Score distribution</strong><p>Poisson outcomes convert expected runs into win and total probabilities</p></div><em>ACTIVE</em></div><div><span className="check-icon warn">!</span><div><strong>Calibration scope</strong><p>{model?.calibrationScope??"Waiting for model metadata"} · feature cutoff {model?.featureCutoff??"—"}.</p></div><em>{model?.calibrated?"ACTIVE":"PENDING"}</em></div></div></article><article className="panel" id="sources"><div className="section-head"><div><p className="eyebrow">DATA LINEAGE</p><h2>Source health</h2></div><span className="live-tag"><i/> LIVE</span></div><div className="source-list"><div><span className="source-icon">MLB</span><div><strong>Official MLB feed</strong><p>Schedule · probable pitchers · weather · venue history · run totals</p></div><span className="source-state healthy">live</span></div><div><span className="source-icon">$</span><div><strong>Sportsbook prices</strong><p>{oddsFeed?.configured?"Automatic consensus for ML and totals; manual props":"Manual two-sided entry with no-vig conversion"}</p></div><span className={`source-state ${oddsFeed?.configured?"healthy":"review"}`}>{oddsFeed?.configured?"live":"manual"}</span></div><div><span className="source-icon">DB</span><div><strong>Recommendation ledger</strong><p>Persistent gated decisions, CLV and official settlement</p></div><span className="source-state healthy">live</span></div></div></article></section>
      <GameStudy game={active} picks={active?pickBoard.byGame.get(active.id)??[]:[]}/>
      <OpportunityBoard games={games} board={pickBoard} onSelect={id=>{setSelected(id);document.getElementById("game-study")?.scrollIntoView({behavior:"smooth"});}}/>
      <ShadowAudit performance={prospective}/>
      <footer><span>Baseline v0.26 · Automatic model-pick board</span><span>Probabilities are estimates, not guarantees. Bet responsibly.</span></footer></section>
  </main>;
}
